import { test, expect } from '@playwright/test';

test.describe('Home Page Navigation via Logo', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should navigate to home page when logo is clicked', async ({ page }) => {
    // Verify logo is visible
    const logo = page.getByRole('img', { name: /logo/i });
    await expect(logo).toBeVisible();

    // Verify home page content is visible
    const homeTitle = page.getByRole('heading', { name: /home/i });
    await expect(homeTitle).toBeVisible();

    // Verify navigation link is visible
    const navLink = page.getByRole('link', { name: /home/i });
    await expect(navLink).toBeVisible();

    // Click the logo using getByRole
    await logo.click();

    // Verify navigation link is no longer visible
    await expect(navLink).not.toBeVisible();

    // Verify home page content is still visible
    await expect(homeTitle).toBeVisible();
  });

  test('should handle logo click when home page is already active', async ({ page }) => {
    // Navigate to home page
    await page.goto('/');

    // Verify home page content is visible
    const homeTitle = page.getByRole('heading', { name: /home/i });
    await expect(homeTitle).toBeVisible();

    // Verify navigation link is visible
    const navLink = page.getByRole('link', { name: /home/i });
    await expect(navLink).toBeVisible();

    // Click the logo using getByRole
    await page.getByRole('img', { name: /logo/i }).click();

    // Verify navigation link is still visible (should not disappear)
    await expect(navLink).toBeVisible();

    // Verify home page content is still visible
    await expect(homeTitle).toBeVisible();
  });
});
